// 4a. JD Quality Gate — deterministic; rejects malformed scrapes before LLM spend.
// Source of truth: src/jdQualityGate.js (kept in sync manually).

const job = $json;
const title = String(job?.title || "").trim();
const company = String(job?.company || "").trim();
const description = String(job?.description || "");

const JD_STRUCTURE_PATTERN = /responsibilities|requirements|qualifications|tasks|aufgaben|profil|anforderungen|qualifikation|deine aufgaben|das bringst du mit|womit du arbeitest|was du mitbringst|must.haves|nice.to.haves/i;
const BOILERPLATE_PATTERN = /cookie|datenschutz|privacy policy|impressum|equal opportunity employer|gleiche chancen|legal notice|terms of service|nutzungsbedingungen/gi;

let reject_reason = null;
if (!title) reject_reason = "title_missing";
else if (!company || /^unknown$/i.test(company) || /^n\.?\s*a\.?$/i.test(company)) reject_reason = "company_missing";
else if (description.length < 600) reject_reason = "description_too_short";
else if (!JD_STRUCTURE_PATTERN.test(description)) reject_reason = "no_jd_structure";
else {
  const matches = description.match(BOILERPLATE_PATTERN) || [];
  const boilerplateChars = matches.reduce((s, m) => s + m.length, 0);
  if (boilerplateChars / description.length > 0.05 && matches.length > 8) {
    reject_reason = "boilerplate_heavy";
  }
}

return {
  json: {
    ...$json,
    _jdQuality: {
      ok: reject_reason === null,
      reason: reject_reason,
    },
  },
};

const job = $json;
const now = new Date();
return {
  json: {
    Date: now.toISOString().slice(0, 10),
    Company: job.company || '',
    Role: job.title || '',
    Source: job.source || '',
    'Job URL': job.url || '',
    'Reject Reason': 'jd_quality_low',
    'Reject Detail': job._jdQuality?.reason || 'unknown',
  },
};

// 12a. Decide Language — deterministic; sets outputLanguage as a hard variable
// Source of truth: src/languageGate.js (kept in sync manually).

const item = $json;
const description = String(item.description || "");
const wordCount = (description.match(/\b\w+\b/g) || []).length || 1;

const GERMAN_TOKENS = /\b(der|die|das|und|oder|f\u00fcr|mit|bei|von|zu|nach|\u00fcber|unter|gegen|durch|ohne|aber|wenn|weil|dass|sind|haben|werden|wird|wurde|kann|muss|ist|war|nicht|auch|schon|noch|sehr|viel|mehr|weniger|gut|gute|guten|neuen|alle|jeden|deine|deiner|deinem|unser|unsere|unseren|aufgaben|anforderungen|kenntnisse|erfahrung|f\u00e4higkeiten|kollegen|umfeld|bereich|m\u00f6glichkeiten|entwicklung|l\u00f6sungen)\b/gi;

const germanMatches = (description.match(GERMAN_TOKENS) || []).length;
const germanRatio = germanMatches / wordCount;
const outputLanguage = germanRatio > 0.08 ? "de" : "en";

return {
  json: {
    ...item,
    outputLanguage,
  },
};

const items = $input.all();
if (items.length === 0) return [];
const merged = { ...items[0].json };
for (const item of items.slice(1)) {
  Object.assign(merged, item.json);
}
merged['Email Recipient'] = merged.hrEmail || '—';
merged['Email Sent'] = merged.emailSent ? 'yes' : 'no';
merged['Telegram Notified'] = merged.telegramNotified ? 'yes' : 'no';
merged['Portal Status'] = 'pending';
const internal = ['hrEmail','emailSent','telegramNotified','_resumeUrl','_coverLetterUrl','_confidence','_company','_role','_language','_jobUrl','_applyUrl','_board','pd_name','pd_email','pd_phone','pd_linkedin','pd_university','pd_degree','pd_availability'];
for (const f of internal) delete merged[f];
return [{ json: merged }];

const company = $json._company || '';
return [{
  json: {
    ...$json,
    apolloPayload: {
      q_organization_name: company,
      person_titles: ['recruiter', 'talent acquisition', 'HR manager', 'head of HR', 'personal'],
      per_page: 1
    }
  }
}];

const people = $json.people || [];
const person = people.find(p => p.email) || null;
const hrEmail = person ? person.email : null;
const hrName = person ? `${person.first_name || ''} ${person.last_name || ''}`.trim() : null;
return [{ json: { ...$json, hrEmail, hrName, emailSent: false } }];

const lang = $json._language || 'de';
const role = $json._role || '';
const company = $json._company || '';
const body = $json.choices?.[0]?.message?.content || '';
const isDE = lang !== 'en';
const subject = isDE ? `Bewerbung als ${role} – Karan Patel` : `Application for ${role} – Karan Patel`;
const greeting = isDE ? 'Sehr geehrte Damen und Herren,' : 'Dear Hiring Manager,';
const closing = isDE ? 'Mit freundlichen Grüßen,\nKaran Patel' : 'Kind regards,\nKaran Patel';
const fullBody = `${greeting}\n\n${body}\n\n${closing}`;
return [{ json: { ...$json, emailSubject: subject, emailBody: fullBody } }];

